import csv
import os

cbsas = [
    "Portland-Vancouver-Hillsboro, OR-WA",
    "Wichita, KS",
    "San Diego-Carlsbad, CA"
]

results = {}

for year in range(2000, 2011):
    fname = f"daily_42101_{year}.csv"
    if not os.path.exists(fname):
        print(f"Missing {fname}")
        continue

    cbsa_daily_aqi = {c: {} for c in cbsas}

    with open(fname, 'r') as f:
        reader = csv.reader(f)
        header = next(reader)
        for row in reader:
            cbsa = row[27]
            if cbsa in cbsas:
                sample_dur = row[9]
                if sample_dur == "8-HR RUN AVG END HOUR":
                    date = row[11]
                    aqi_str = row[19]
                    if aqi_str and aqi_str != '':
                        try:
                            aqi = int(aqi_str)
                        except:
                            continue
                        if date not in cbsa_daily_aqi[cbsa]:
                            cbsa_daily_aqi[cbsa][date] = []
                        cbsa_daily_aqi[cbsa][date].append(aqi)

    results[year] = {}
    for cbsa in cbsas:
        if len(cbsa_daily_aqi[cbsa]) == 0:
            results[year][cbsa] = None
            continue
        all_good = True
        for date, aqi_vals in cbsa_daily_aqi[cbsa].items():
            if max(aqi_vals) > 50:
                all_good = False
                # Show the bad date
                print(f"  {year} {cbsa}: AQI {max(aqi_vals)} on {date}")
                break
        results[year][cbsa] = all_good

print(f"\n{'Year':<6} {'Portland':<12} {'Wichita':<12} {'San Diego':<12}")
print("-" * 42)
good_years = []
for year in range(2000, 2011):
    portland = results.get(year, {}).get("Portland-Vancouver-Hillsboro, OR-WA")
    wichita = results.get(year, {}).get("Wichita, KS")
    sandiego = results.get(year, {}).get("San Diego-Carlsbad, CA")

    p_str = str(portland) if portland is not None else "No data"
    w_str = str(wichita) if wichita is not None else "No data"
    s_str = str(sandiego) if sandiego is not None else "No data"

    print(f"{year:<6} {p_str:<12} {w_str:<12} {s_str:<12}")

    if portland and wichita and sandiego:
        good_years.append(year)

print(f"\nYears where ALL THREE had all Good: {good_years}")
