cd /tmp/epa_data && python3 << 'EOF'
import csv
import os

cbsas = [
    "Portland-Vancouver-Hillsboro, OR-WA",
    "Wichita, KS",
    "San Diego-Carlsbad, CA"
]

for year in [2008, 2009, 2010]:
    fname = f"daily_42101_{year}.csv"
    cbsa_dates = {c: set() for c in cbsas}
    cbsa_max_aqi = {c: 0 for c in cbsas}

    with open(fname, 'r') as f:
        reader = csv.reader(f)
        header = next(reader)
        for row in reader:
            cbsa = row[27]
            if cbsa in cbsas:
                sample_dur = row[9]
                if sample_dur == "8-HR RUN AVG END HOUR":
                    date = row[11]
                    aqi_str = row[19]
                    if aqi_str and aqi_str != '':
                        try:
                            aqi = int(aqi_str)
                        except:
                            continue
                        cbsa_dates[cbsa].add(date)
                        if aqi > cbsa_max_aqi[cbsa]:
                            cbsa_max_aqi[cbsa] = aqi

    # Check days in year
    import datetime
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        expected_days = 366
    else:
        expected_days = 365

    print(f"\n=== {year} (expected {expected_days} days) ===")
    for cbsa in cbsas:
        n_dates = len(cbsa_dates[cbsa])
        max_aqi = cbsa_max_aqi[cbsa]
        print(f"  {cbsa}: {n_dates} days with data, max AQI = {max_aqi}")
        if n_dates < expected_days:
            # Find missing dates
            all_dates = set()
            d = datetime.date(year, 1, 1)
            while d.year == year:
                all_dates.add(d.isoformat())
                d += datetime.timedelta(days=1)
            missing = sorted(all_dates - cbsa_dates[cbsa])
            if missing:
                print(f"    Missing dates: {missing[:10]}{'...' if len(missing) > 10 else ''}")
EOF
